/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

rl.on("line", (line) => {
  const arr = line.split(",");

  arr.sort((a, b) => {
    const s1 = a + b;
    const s2 = b + a;
    return s1 == s2 ? 0 : s1 > s2 ? -1 : 1;
  });

  console.log(arr.join(""));
});

