#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 25

int cmp(const void* a, const void* b) {
    char* A = *((char**) a);
    char* B = *((char**) b);

    char AB[10000] = {'\0'};
    strcat(AB, A);
    strcat(AB, B);

    char BA[10000] = {'\0'};
    strcat(BA, B);
    strcat(BA, A);

    return strcmp(BA, AB);
}

int main() {
    char line[10000];
    gets(line);

    char* ss[MAX_SIZE];
    int ss_size = 0;

    char* token = strtok(line, ",");
    while(token != NULL) {
        ss[ss_size++] = token;
        token = strtok(NULL, ",");
    }

    qsort(ss, ss_size, sizeof(char*), cmp);

    char res[10000];
    for(int i=0; i<ss_size; i++) {
        strcat(res, ss[i]);
    }

    puts(res);

    return 0;
}
